import java.util.*;
import java.io.*;

public class Main {
    static final int N = 10;
    static final int M = 1000007;
    static final int K = 200;
    static final int p = 1000000007;
    static class BitSet40 {
        long[] bits = new long[1]; // only 40 bits needed
        public BitSet40() {
            bits[0] = 0L;
        }
        public void set(int index) {
            bits[0] |= (1L << index);
        }
        public boolean get(int index) {
            return ((bits[0] >> index) & 1L) == 1L;
        }
        public void or(BitSet40 other) {
            this.bits[0] |= other.bits[0];
        }
        public boolean equals(BitSet40 other) {
            return this.bits[0] == other.bits[0];
        }
        public BitSet40 clone() {
            BitSet40 clone = new BitSet40();
            clone.bits[0] = this.bits[0];
            return clone;
        }
    }

    static int n;
    static int[] e = new int[N];
    static int[] s = new int[M];
    static int[] wf = new int[K];
    static int[][] q = new int[N][K];
    static int[][] f = new int[N + 1][N + 1];
    static int[][] ans = new int[N + 1][M];
    static BitSet40[] wq = new BitSet40[N + 1][M];
    static Map<String, Integer>[] rt = new HashMap[N + 1];

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static int readInt() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return Integer.parseInt(st.nextToken());
    }

    static long mod_pow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return result;
    }

    static void process_node(int u) {
        q[u][0] = 0;
        int os = 0, of = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (s[i] == u) {
                q[u][++q[u][0]] = i;
                wf[i] = ++os;
            }
        }
        for (int i = 1; i <= e[u - 1]; i++) {
            if (ans[u - 1][i] == 0) continue;
            for (int h = 1; h < (1 << n); h++) {
                long opq = 1;
                for (int c = 0; c < n; c++) {
                    if (((1 << c) & h) != 0) {
                        opq = (opq * f[u][c + 1]) % p;
                    } else {
                        opq = (opq * (1 - f[u][c + 1] + p) % p) % p;
                    }
                }
                BitSet40 c = wq[u - 1][i].clone();
                BitSet40 hc = new BitSet40();
                for (int x = 1; x <= q[u - 1][0]; x++) {
                    if (c.get(x - 1)) {
                        for (int t = 0; t < n; t++) {
                            if ((((1 << t) & h) != 0) && ((q[u - 1][x] & (1 << t)) == 0)) {
                                int pos = wf[q[u - 1][x] | (1 << t)];
                                // set bit at position pos-1
                                // Since bits are 0-indexed
                                // We need to set bit at position pos-1
                                // But in the original code, q[u-1][x] is an integer, so we set bit at position wf[q[u-1][x]|(1<<t)]
                                // which is wf[q[u-1][x]|(1<<t)] - 1 in 0-based index
                                // But in our implementation, we can just set bits accordingly
                                // So, set bit at position wf[q[u-1][x]|(1<<t)] - 1
                                // But since wf[q[u-1][x]|(1<<t)] is 1-based, subtract 1
                                // So, set bit at position wf[q[u-1][x]|(1<<t)] - 1
                                // But in our code, we can just set bit at position wf[q[u-1][x]|(1<<t)] - 1
                                // Let's do that
                                int bitPos = wf[q[u - 1][x] | (1 << t)] - 1;
                                hc.set(bitPos);
                            }
                        }
                    }
                }
                boolean tg = false;
                // Check if hc is new
                String hcKey = Long.toString(hc.bits[0]);
                if (!rt[u].containsKey(hcKey)) {
                    rt[u].put(hcKey, ++of);
                    e[u]++;
                    wq[u][e[u]] = hc;
                }
                int pos = rt[u].get(hcKey);
                ans[u][pos] = (ans[u][pos] + (int)((opq * ans[u - 1][i]) % p)) % p;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        n = readInt();
        for (int i = 0; i <= (1 << n); i++) {
            s[i] = Integer.bitCount(i);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int val = readInt();
                f[i][j] = (int)((val * mod_pow(100, p - 2)) % p);
            }
        }
        // Initialize
        ans[0][1] = 1;
        wq[0][1] = new BitSet40();
        wq[0][1].set(0); // set bit 0 to 1
        e[0] = 1;
        rt = new HashMap[N + 1];
        for (int i = 0; i <= N; i++) {
            rt[i] = new HashMap<>();
        }
        rt[0].put("1", 1);
        for (int i = 1; i <= n; i++) {
            process_node(i);
        }
        System.out.println(ans[n][1]);
    }
}
